define('taoQtiTest/controller/creator/helpers/qtiTest',['jquery', 'lodash', 'taoQtiTest/controller/creator/helpers/validators', 'taoQtiTest/controller/creator/helpers/rubricBlockAudience'], function ($, _, validators, rubricBlockAudience) {
  'use strict';
  var qtiTestHelper = {
    consolidateRubricBlocks(sectionLikeModel) {
      if (!sectionLikeModel || !_.isObject(sectionLikeModel)) {
        return;
      }
      if (_.isArray(sectionLikeModel.rubricBlocks)) {
        if (sectionLikeModel.rubricBlocks.length === 0 || sectionLikeModel.rubricBlocks.length === 1 && sectionLikeModel.rubricBlocks[0].content.length === 0) {
          delete sectionLikeModel.rubricBlocks;
        } else {
          _.forEach(sectionLikeModel.rubricBlocks, function (rubricBlock) {
            rubricBlock.view = rubricBlockAudience.getValidView(rubricBlock.view, rubricBlock.views);
            rubricBlock.views = [rubricBlock.view];
          });
        }
      }
      if (_.isArray(sectionLikeModel.sectionParts)) {
        _.forEach(sectionLikeModel.sectionParts, this.consolidateRubricBlocks.bind(this));
      }
    },
    getIdentifiers: function getIdentifiers(model, includesOnlyTypes, excludeTypes) {
      return _.uniq(_.map(validators.extractIdentifiers(model, includesOnlyTypes, excludeTypes), 'identifier'));
    },
    getIdentifiersOf: function getIdentifiersOf(model, qtiType) {
      return this.getIdentifiers(model, [qtiType]);
    },
    filterQtiType: function filterQtiType(value, type) {
      return value['qti-type'] && value['qti-type'] === type;
    },
    addMissingQtiType: function addMissingQtiType(collection, parentType) {
      _.forEach(collection, (value, key) => {
        if (_.isObject(value) && !_.isArray(value) && !_.has(value, 'qti-type')) {
          if (_.isNumber(key)) {
            if (parentType) {
              value['qti-type'] = parentType;
            }
          } else {
            value['qti-type'] = key;
          }
        }
        if (_.isArray(value)) {
          this.addMissingQtiType(value, key.replace(/s$/, ''));
        } else if (_.isObject(value)) {
          this.addMissingQtiType(value);
        }
      });
    },
    consolidateModel: function consolidateModel(model) {
      if (model && model.testParts && _.isArray(model.testParts)) {
        _.forEach(model.testParts, testPart => {
          if (testPart.assessmentSections && _.isArray(testPart.assessmentSections)) {
            _.forEach(testPart.assessmentSections, assessmentSection => {
              if (assessmentSection.ordering && typeof assessmentSection.ordering.shuffle !== 'undefined' && assessmentSection.ordering.shuffle === false) {
                delete assessmentSection.ordering;
              }
              if (assessmentSection.sectionParts && _.isArray(assessmentSection.sectionParts)) {
                _.forEach(assessmentSection.sectionParts, part => {
                  if (part.categories && _.isArray(part.categories) && (part.categories.length === 0 || part.categories[0].length === 0)) {
                    part.categories = [];
                  }
                });
              }
              this.consolidateRubricBlocks(assessmentSection);
            });
          }
        });
      }
      return model;
    },
    getAvailableIdentifier: function getAvailableIdentifier(model, qtiType, suggestion) {
      var index = 1;
      var glue = '-';
      var identifier;
      var current;
      if (_.includes(validators.qtiTypesForUniqueIds, qtiType)) {
        current = this.getIdentifiers(model, validators.qtiTypesForUniqueIds);
      } else {
        current = this.getIdentifiersOf(model, qtiType);
      }
      suggestion = suggestion || qtiType;
      do {
        identifier = suggestion + glue + index++;
      } while (_.includes(current, identifier.toUpperCase()) || $("#".concat(identifier)).length);
      return identifier;
    }
  };
  return qtiTestHelper;
});
